const $ = (s, root=document) => root.querySelector(s);
const state = { token: localStorage.getItem('mobrix_token'), user: null, company: null, page: 'dashboard', cache: {}, sidebarCollapsed: localStorage.getItem('madevix_sidebar_collapsed') === '1', classic: { tab:'orcamento', items:[], pieces:[], client:'', markup:0 } };
try { state.classic = { ...state.classic, ...JSON.parse(localStorage.getItem('mobrix_classic') || '{}') }; } catch {}
function saveClassic(){ try { localStorage.setItem('mobrix_classic', JSON.stringify(state.classic)); } catch {} }
const pageMeta = {
  dashboard:['PAINEL DE CONTROLE','Dashboard'],
  projects:['GESTÃO DE PROJETOS','Projetos e móveis'],
  orders:['CHÃO DE FÁBRICA','Ordens de produção'],
  engineering:['ENGENHARIA','Ficha técnica e peças'],
  offcuts:['APROVEITAMENTO','Banco de retalhos'],
  productivity:['INDICADORES INDUSTRIAIS','Produtividade e horas'],
  classic:['FERRAMENTAS DE MARCENARIA','Ferramentas clássicas'],
  customers:['RELACIONAMENTO','Clientes'],
  materials:['CONTROLE DE MATERIAIS','Estoque e materiais'],purchasing:['PLANEJAMENTO DE MATERIAIS','Compra inteligente'],
  finance:['CONTROLE FINANCEIRO','Financeiro'],
  settings:['PREFERÊNCIAS','Configurações']
};
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => Number(value || 0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date = value => value ? new Date(value+'T00:00:00').toLocaleDateString('pt-BR') : '—';
const statusLabel = s => ({orcamento:'Orçamento',aprovado:'Aprovado',producao:'Em produção',concluido:'Concluído',cancelado:'Cancelado',planejamento:'Planejamento',corte:'Corte',usinagem:'Usinagem',montagem:'Montagem',acabamento:'Acabamento',instalacao:'Instalação',pausado:'Pausado'})[s] || s || '—';
const pillClass = s => ['concluido','aprovado'].includes(s) ? 'green' : ['cancelado','atrasado'].includes(s) ? 'red' : ['orcamento','planejamento'].includes(s) ? 'orange' : '';
async function api(url, options={}) {
  const response = await fetch('/api'+url,{...options,headers:{'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...(options.headers||{})}});
  const data = await response.json().catch(()=>({}));
  if (!response.ok) { if(response.status===401){logout(false)} throw new Error(data.error || 'Não foi possível concluir a operação.'); }
  return data;
}
function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('#toast-root').append(node);setTimeout(()=>node.remove(),3400)}
function showAuth(register=false){$('#auth-screen').classList.remove('hidden');$('#app').classList.add('hidden');$('#login-form').classList.toggle('hidden',register);$('#register-form').classList.toggle('hidden',!register);$('#auth-title').innerHTML=register?'Comece a organizar<br><span>sua produção.</span>':'Sua marcenaria,<br><span>sob controle.</span>';$('#auth-description').textContent=register?'Crie o ambiente da sua empresa no MADEVIX.':'Entre para acompanhar sua operação.';$('#auth-switch').innerHTML=register?'Já possui acesso? <button type="button" id="show-login">Fazer login</button>':'Ainda não tem acesso? <button type="button" id="show-register">Criar empresa</button>';$('#auth-error').textContent=''}
function showApp(){ $('#auth-screen').classList.add('hidden');$('#app').classList.remove('hidden');$('#user-name').textContent=state.user?.name||'Usuário';$('#user-role').textContent=state.user?.role==='admin'?'Administrador':'Equipe';$('#user-avatar').textContent=(state.user?.name||'M').slice(0,1).toUpperCase();$('#profile-shortcut').textContent=(state.user?.name||'M').slice(0,1).toUpperCase();$('#company-name').textContent=state.company?.name||'Minha empresa';$('#today').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});$('#sidebar').classList.toggle('collapsed',state.sidebarCollapsed);$('#sidebar-collapse').setAttribute('aria-label',state.sidebarCollapsed?'Expandir sidebar':'Recolher sidebar');$('#sidebar-collapse').title=state.sidebarCollapsed?'Expandir menu':'Recolher menu';renderNavIcons();}
function logout(notify=true){state.token=null;state.user=null;state.company=null;localStorage.removeItem('mobrix_token');showAuth();if(notify)toast('Você saiu da sua conta.')}
async function initialize(){if(!state.token){showAuth();return}try{const data=await api('/me');state.user=data.user;state.company=data.company;showApp();await navigate('dashboard')}catch{logout(false)}}
$('#auth-switch').addEventListener('click',e=>{if(e.target.id==='show-register')showAuth(true);if(e.target.id==='show-login')showAuth(false)});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);$('#auth-error').textContent='';try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.token=d.token;state.user=d.user;localStorage.setItem('mobrix_token',d.token);await initialize()}catch(err){$('#auth-error').textContent=err.message}});
$('#register-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);$('#auth-error').textContent='';try{const d=await api('/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.token=d.token;state.user=d.user;localStorage.setItem('mobrix_token',d.token);await initialize()}catch(err){$('#auth-error').textContent=err.message}});
$('#logout').addEventListener('click',()=>logout());
$('#profile-shortcut').addEventListener('click',()=>navigate('settings'));
$('#mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#sidebar-overlay')?.classList.toggle('visible',open)});
$('#sidebar-collapse').addEventListener('click',()=>{state.sidebarCollapsed=!state.sidebarCollapsed;const sidebar=$('#sidebar');sidebar.classList.toggle('collapsed',state.sidebarCollapsed);const button=$('#sidebar-collapse');button.setAttribute('aria-label',state.sidebarCollapsed?'Expandir sidebar':'Recolher sidebar');button.title=state.sidebarCollapsed?'Expandir menu':'Recolher menu';localStorage.setItem('madevix_sidebar_collapsed',state.sidebarCollapsed?'1':'0')});
$('#alerts-button').addEventListener('click',showOperationalAlerts);
$('#global-search-results').addEventListener('click',e=>{const item=e.target.closest('[data-search-page]');if(item)navigate(item.dataset.searchPage)});
$('#global-search').addEventListener('input',handleGlobalSearch);
$('#global-search').addEventListener('keydown',e=>{if(e.key==='Escape')$('#global-search-results').classList.add('hidden');if(e.key==='Enter'){const first=$('#global-search-results [data-search-page]');if(first)navigate(first.dataset.searchPage)}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search')?.focus()}});

$('.nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page)});
async function navigate(page){if(page!=='classic'){if(furnitureViewer){furnitureViewer.destroy();furnitureViewer=null}if(importedModelViewer){importedModelViewer.destroy();importedModelViewer=null}}state.page=page;$('.nav-item.active')?.classList.remove('active');$('[data-page="'+page+'"]')?.classList.add('active');$('#page-kicker').textContent=pageMeta[page][0];$('#page-title').textContent=pageMeta[page][1];$('#sidebar').classList.remove('open');$('#sidebar-overlay')?.classList.remove('visible');$('#global-search').value='';$('#global-search-results').classList.add('hidden');$('#page-content').classList.remove('page-enter');void $('#page-content').offsetWidth;$('#page-content').classList.add('page-enter');$('#page-content').innerHTML='<div class="loading"><span class="loading-mark"></span>Carregando dados...</div>';try{if(page==='dashboard')await renderDashboard();else if(page==='settings')renderSettings();else if(['engineering','offcuts','productivity'].includes(page))await renderIndustrial(page);else if(page==='purchasing')await renderPurchasing();else if(page==='classic')renderClassic();else await renderResource(page)}catch(e){$('#page-content').innerHTML='<div class="panel empty-state">'+esc(e.message)+'</div>'}}
async function renderDashboard(){
 const [d,projects,orders,finance,customers,materials]=await Promise.all([api('/dashboard'),api('/projects'),api('/orders'),api('/finance'),api('/customers'),api('/materials')]);
 const now=new Date(),monthStart=new Date(now.getFullYear(),now.getMonth(),1),nextWeek=new Date(now.getFullYear(),now.getMonth(),now.getDate()+7);
 const paid=finance.filter(x=>x.paid_at),monthPaid=paid.filter(x=>new Date(x.paid_at)>=monthStart);
 const income=monthPaid.filter(x=>x.transaction_type==='receita').reduce((n,x)=>n+Number(x.amount||0),0);
 const expenses=monthPaid.filter(x=>x.transaction_type==='despesa').reduce((n,x)=>n+Number(x.amount||0),0);
 const pendingQuotes=projects.filter(x=>x.status==='orcamento').length;
 const upcoming=orders.filter(x=>x.due_date&&new Date(x.due_date+'T23:59:59')>=now&&new Date(x.due_date+'T00:00:00')<=nextWeek&&x.stage!=='concluido');
 const overdue=orders.filter(x=>x.due_date&&new Date(x.due_date+'T23:59:59')<now&&x.stage!=='concluido'&&x.stage!=='pausado');
 const lowStock=materials.filter(x=>Number(x.quantity)<=Number(x.minimum_quantity));
 const fmtMonth=d=>d.toLocaleDateString('pt-BR',{month:'short'}).replace('.','');
 const months=Array.from({length:6},(_,i)=>new Date(now.getFullYear(),now.getMonth()-5+i,1));
 const chartRows=months.map(m=>{const next=new Date(m.getFullYear(),m.getMonth()+1,1);const items=paid.filter(x=>new Date(x.paid_at)>=m&&new Date(x.paid_at)<next);return{label:fmtMonth(m),income:items.filter(x=>x.transaction_type==='receita').reduce((n,x)=>n+Number(x.amount||0),0),expense:items.filter(x=>x.transaction_type==='despesa').reduce((n,x)=>n+Number(x.amount||0),0)}});
 const maxChart=Math.max(1,...chartRows.flatMap(x=>[x.income,x.expense]));
 const chart=chartRows.map(x=>'<div class="chart-column" title="'+x.label+': receitas '+money(x.income)+' · despesas '+money(x.expense)+'"><div class="chart-bars"><span class="chart-bar income" style="height:'+Math.max(3,x.income/maxChart*100)+'%"></span><span class="chart-bar expense" style="height:'+Math.max(3,x.expense/maxChart*100)+'%"></span></div><small>'+esc(x.label)+'</small></div>').join('');
 const activities=[
  ...projects.slice(0,5).map(x=>({date:x.created_at,label:'Projeto cadastrado',detail:x.title,status:statusLabel(x.status),time:x.created_at})),
  ...orders.slice(0,5).map(x=>({date:x.created_at,label:'Ordem de produção',detail:'OP #'+x.code,status:statusLabel(x.stage),time:x.created_at})),
  ...customers.slice(0,4).map(x=>({date:x.created_at,label:'Novo cliente',detail:x.name,status:'Cadastro',time:x.created_at})),
  ...finance.slice(0,4).map(x=>({date:x.created_at,label:'Movimentação financeira',detail:x.description,status:x.transaction_type==='receita'?'Receita':'Despesa',time:x.created_at}))
 ].filter(x=>x.time).sort((a,b)=>new Date(b.time)-new Date(a.time)).slice(0,7);
 const activityHtml=activities.length?activities.map(x=>'<div class="activity-item"><span class="activity-marker"></span><div class="activity-copy"><strong>'+esc(x.label)+'</strong><small>'+esc(x.detail)+'</small></div><span class="activity-status">'+esc(x.status)+'</span><time>'+new Date(x.time).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})+'</time></div>').join(''):'<div class="empty-state">As atividades registradas aparecerão aqui.</div>';
 const nextItems=[
  ...overdue.slice(0,4).map(x=>({title:'OP #'+x.code,detail:'Prazo vencido · '+(x.project_title||'Ordem de produção'),kind:'Atrasada',tone:'red'})),
  ...upcoming.slice(0,5).map(x=>({title:'OP #'+x.code,detail:'Entrega até '+date(x.due_date),kind:'Próxima',tone:'orange'}))
 ].slice(0,5);
 $('#alert-indicator').classList.toggle('visible',Boolean(lowStock.length||overdue.length));
 $('#page-content').innerHTML=`
 <section class="dashboard-intro">
  <div><p class="eyebrow">VISÃO OPERACIONAL · ${now.toLocaleDateString('pt-BR',{month:'long',year:'numeric'}).toUpperCase()}</p><h2>Bom dia, ${esc((state.user?.name||'').split(' ')[0]||'equipe')}.</h2><p>Veja o que está acontecendo na operação da <strong>${esc(state.company?.name||'sua empresa')}</strong>.</p></div>
  <div class="intro-actions"><span class="today-chip">${now.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'})}</span><button class="btn btn-primary" data-action="new-project"><span aria-hidden="true">＋</span> Novo projeto</button></div>
 </section>
 <section class="stats-grid dashboard-stats">
  <article class="stat-card"><div class="stat-head"><span>Faturamento do mês</span><span class="stat-icon" data-icon="trending"></span></div><div class="stat-value">${money(income)}</div><div class="stat-foot">Receitas marcadas como pagas</div></article>
  <article class="stat-card"><div class="stat-head"><span>Resultado do mês</span><span class="stat-icon" data-icon="chart"></span></div><div class="stat-value">${money(income-expenses)}</div><div class="stat-foot">Receitas menos despesas pagas</div></article>
  <article class="stat-card"><div class="stat-head"><span>Orçamentos pendentes</span><span class="stat-icon" data-icon="file"></span></div><div class="stat-value">${pendingQuotes}</div><div class="stat-foot">Projetos aguardando aprovação</div></article>
  <article class="stat-card"><div class="stat-head"><span>Projetos em andamento</span><span class="stat-icon" data-icon="folder"></span></div><div class="stat-value">${d.projects.active}</div><div class="stat-foot">${d.projects.total} projetos cadastrados</div></article>
  <article class="stat-card"><div class="stat-head"><span>Ordens em produção</span><span class="stat-icon" data-icon="factory"></span></div><div class="stat-value">${d.orders.active}</div><div class="stat-foot">${d.orders.total} ordens registradas</div></article>
  <article class="stat-card"><div class="stat-head"><span>Entregas próximas</span><span class="stat-icon" data-icon="calendar"></span></div><div class="stat-value">${upcoming.length}</div><div class="stat-foot">${overdue.length} ordens com prazo vencido</div></article>
  <article class="stat-card"><div class="stat-head"><span>Estoque baixo</span><span class="stat-icon" data-icon="package"></span></div><div class="stat-value">${lowStock.length}</div><div class="stat-foot">Materiais no mínimo ou abaixo</div></article>
 </section>
 <div class="dashboard-grid dashboard-grid-primary">
  <section class="panel chart-panel"><div class="panel-head"><div><p class="eyebrow">FINANCEIRO</p><h3>Receitas e despesas</h3><p>Movimentações pagas · últimos seis meses</p></div><button class="text-link" data-page="finance">Abrir financeiro <span>→</span></button></div>
   <div class="chart-legend"><span><i class="legend-dot income"></i>Receitas</span><span><i class="legend-dot expense"></i>Despesas</span></div>
   <div class="chart-area"><div class="chart-y-labels"><span>${money(maxChart)}</span><span>${money(maxChart/2)}</span><span>R$ 0</span></div><div class="chart-plot"><div class="chart-gridlines"><i></i><i></i><i></i></div><div class="chart-columns">${chart}</div></div></div>
  </section>
  <section class="panel pipeline-panel"><div class="panel-head"><div><p class="eyebrow">COMERCIAL</p><h3>Carteira de projetos</h3><p>Distribuição por situação atual</p></div><button class="text-link" data-page="projects">Ver projetos <span>→</span></button></div>
   <div class="pipeline-total"><strong>${money(d.projects.pipeline)}</strong><span>Valor em carteira ativa</span></div>
   <div class="pipeline-list">${[['Orçamento','orcamento'],['Aprovado','aprovado'],['Em produção','producao'],['Concluído','concluido']].map(([label,key])=>{const count=projects.filter(p=>p.status===key).length;const pct=projects.length?count/projects.length*100:0;return '<div class="pipeline-row"><div><span>'+label+'</span><strong>'+count+'</strong></div><div class="pipeline-track"><i style="width:'+pct+'%"></i></div></div>'}).join('')}</div>
  </section>
 </div>
 <div class="dashboard-grid dashboard-grid-secondary">
  <section class="panel"><div class="panel-head"><div><p class="eyebrow">ACOMPANHAMENTO</p><h3>Atividades recentes</h3><p>Registros mais recentes do ambiente</p></div></div><div class="activity-list">${activityHtml}</div></section>
  <section class="panel"><div class="panel-head"><div><p class="eyebrow">AGENDA OPERACIONAL</p><h3>Prazos e alertas</h3><p>Ordens próximas e atrasadas</p></div><button class="text-link" data-page="orders">Ver produção <span>→</span></button></div>
   <div class="upcoming-list">${nextItems.length?nextItems.map(x=>'<div class="upcoming-item"><span class="upcoming-indicator '+x.tone+'"></span><div><strong>'+esc(x.title)+'</strong><small>'+esc(x.detail)+'</small></div><span class="pill '+x.tone+'">'+x.kind+'</span></div>').join(''):'<div class="empty-state">Nenhum prazo próximo ou vencido identificado.</div>'}
   ${lowStock.length?'<div class="inline-alert"><span class="alert-symbol">!</span><div><strong>'+lowStock.length+' materiais com estoque baixo</strong><small>Confira disponibilidade antes de iniciar novas ordens.</small></div><button class="text-link" data-page="materials">Ver estoque</button></div>':''}</div>
  </section>
 </div>`;
 renderNavIcons();
}

